namespace sv_16591f20ac524b468d54c549abf405ea.Services;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

namespace sv_16591f20ac524b468d54c549abf405ea.Services;

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@namespace sv_16591f20ac524b468d54c549abf405ea.Components.Pages.Apply

<nav class="step-indicator" aria-label="Application progress">
    <ol class="step-list">
        @for (int i = 0; i < StepNames.Count; i++)
        {
            var stepIndex = i;
            var status = GetStepStatus(stepIndex);
            <li class="step-item @status" @onclick="() => OnStepClick(stepIndex)">
                <span class="step-badge">
                    @if (status == "completed")
                    {
                        <span class="checkmark">&#10003;</span>
                    }
                    else
                    {
                        @(stepIndex + 1)
                    }
                </span>
                <span class="step-label">@StepNames[stepIndex]</span>
            </li>
        }
    </ol>
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnStepSelected { get; set; }

    private static readonly List<string> StepNames = new()
    {
        "Personal Info",
        "Work History",
        "References",
        "Cover Letter",
        "Review & Submit"
    };

    private string GetStepStatus(int index)
    {
        if (index == CurrentStep) return "active";
        if (index < CurrentStep) return "completed";
        return "dimmed";
    }

    private async Task OnStepClick(int index)
    {
        if (index < CurrentStep)
        {
            await OnStepSelected.InvokeAsync(index);
        }
    }
}

@namespace sv_16591f20ac524b468d54c549abf405ea.Components.Pages.Apply

<div class="work-entry-card">
    @if (ShowRemove)
    {
        <button type="button" class="btn-remove" @onclick="OnRemove">Remove</button>
    }

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" value="@Company" @onchange="e => UpdateField(nameof(Company), e.Value)" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" value="@Title" @onchange="e => UpdateField(nameof(Title), e.Value)" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@StartDate?.ToString("yyyy-MM-dd")"
                   @onchange="e => UpdateStartDate(e.Value)" />
        </div>
        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@EndDate?.ToString("yyyy-MM-dd")"
                   disabled="@IsCurrent"
                   @onchange="e => UpdateEndDate(e.Value)" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent" @onchange="e => UpdateIsCurrent(e.Value)" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea rows="3" value="@Description" @onchange="e => UpdateField(nameof(Description), e.Value)"></textarea>
    </div>
</div>

@code {
    [Parameter] public string Company { get; set; } = "";
    [Parameter] public string Title { get; set; } = "";
    [Parameter] public DateTime? StartDate { get; set; }
    [Parameter] public DateTime? EndDate { get; set; }
    [Parameter] public bool IsCurrent { get; set; }
    [Parameter] public string Description { get; set; } = "";
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryData> OnChanged { get; set; }

    private void UpdateField(string field, object? value)
    {
        var data = GetCurrentData();
        var str = value?.ToString() ?? "";
        data = field switch
        {
            nameof(Company) => data with { Company = str },
            nameof(Title) => data with { Title = str },
            nameof(Description) => data with { Description = str },
            _ => data
        };
        OnChanged.InvokeAsync(data);
    }

    private void UpdateStartDate(object? value)
    {
        var data = GetCurrentData();
        if (DateTime.TryParse(value?.ToString(), out var date))
            data = data with { StartDate = date };
        OnChanged.InvokeAsync(data);
    }

    private void UpdateEndDate(object? value)
    {
        var data = GetCurrentData();
        if (DateTime.TryParse(value?.ToString(), out var date))
            data = data with { EndDate = date };
        else
            data = data with { EndDate = null };
        OnChanged.InvokeAsync(data);
    }

    private void UpdateIsCurrent(object? value)
    {
        var isCurrent = value is bool b && b;
        var data = GetCurrentData() with { IsCurrent = isCurrent, EndDate = isCurrent ? null : EndDate };
        OnChanged.InvokeAsync(data);
    }

    private WorkEntryData GetCurrentData() => new(Company, Title, StartDate, EndDate, IsCurrent, Description);

    public record WorkEntryData(string Company, string Title, DateTime? StartDate, DateTime? EndDate, bool IsCurrent, string Description);
}

