            field == nameof(Name) ? str : Name,
            field == nameof(Relationship) ? str : Relationship,
            field == nameof(Email) ? str : Email,
            field == nameof(Phone) ? str : Phone
        );
        OnChanged.InvokeAsync(data);
    }

    public record ReferenceData(string Name, string Relationship, string Email, string Phone);
}

