@namespace sv_16591f20ac524b468d54c549abf405ea.Components.Pages.Apply

<div class="step-content">
    <h2>Cover Letter</h2>

    <div class="form-group">
        <label>Write your cover letter</label>
        <textarea rows="12" maxlength="@MaxCharacters" @bind="CoverLetterText"></textarea>
        <div class="char-count @(CoverLetterText.Length > MaxCharacters ? "over-limit" : "")">
            @CoverLetterText.Length / @MaxCharacters characters
        </div>
    </div>

    <div class="step-buttons">
        <button type="button" class="btn-outline" @onclick="OnBack">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public string CoverLetterText { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<string> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private const int MaxCharacters = 2000;

    private async Task HandleNext()
    {
        await OnNext.InvokeAsync(CoverLetterText);
    }
}

@namespace sv_16591f20ac524b468d54c549abf405ea.Components.Pages.Apply
@using sv_16591f20ac524b468d54c549abf405ea.Services

<div class="step-content">
    <h2>Review & Submit</h2>

    @if (IsSubmitted)
    {
        <div class="confirmation">
            <h3>&#10003; Application Submitted!</h3>
            <p>Your application has been received. Your application ID is: <strong>@ApplicationId</strong></p>
        </div>
    }
    else
    {
        @if (!string.IsNullOrEmpty(ErrorMessage))
        {
            <div class="error-message">@ErrorMessage</div>
        }

        <section class="review-section">
            <div class="review-header">
                <h3>Personal Information</h3>
                <button type="button" class="btn-link" @onclick="() => OnEditSection.InvokeAsync(0)">Edit</button>
            </div>
            <dl>
                <dt>Full Name</dt><dd>@Personal.FullName</dd>
                <dt>Email</dt><dd>@Personal.Email</dd>
                <dt>Phone</dt><dd>@Personal.Phone</dd>
                <dt>Address</dt><dd>@Personal.Address</dd>
            </dl>
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>Work History</h3>
                <button type="button" class="btn-link" @onclick="() => OnEditSection.InvokeAsync(1)">Edit</button>
            </div>
            @foreach (var entry in WorkEntries)
            {
                <div class="review-entry">
                    <strong>@entry.Title</strong> at @entry.Company
                    <br />
                    <small>
                        @entry.StartDate?.ToString("MMM yyyy") &mdash;
                        @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))
                    </small>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p>@entry.Description</p>
                    }
                </div>
            }
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>References</h3>
                <button type="button" class="btn-link" @onclick="() => OnEditSection.InvokeAsync(2)">Edit</button>
            </div>
            @foreach (var r in References)
            {
                <div class="review-entry">
                    <strong>@r.Name</strong> (@r.Relationship)
                    <br />
                    <small>@r.Email @(!string.IsNullOrWhiteSpace(r.Phone) ? $"| {r.Phone}" : "")</small>
                </div>
            }
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>Cover Letter</h3>
                <button type="button" class="btn-link" @onclick="() => OnEditSection.InvokeAsync(3)">Edit</button>
            </div>
            <p class="cover-letter-preview">@CoverLetter</p>
        </section>

        <div class="step-buttons">
            <button type="button" class="btn-outline" @onclick="OnBack">Back</button>
            <button type="button" class="btn-primary btn-submit" @onclick="HandleSubmit" disabled="@IsSubmitting">
                @(IsSubmitting ? "Submitting..." : "Submit Application")
            </button>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfo Personal { get; set; } = default!;
    [Parameter, EditorRequired] public List<WorkHistoryStep.EntryModel> WorkEntries { get; set; } = new();
    [Parameter, EditorRequired] public List<ReferencesStep.RefModel> References { get; set; } = new();
    [Parameter, EditorRequired] public string CoverLetter { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnEditSection { get; set; }
    [Parameter, EditorRequired] public EventCallback OnSubmit { get; set; }

    [Parameter] public bool IsSubmitting { get; set; }
    [Parameter] public bool IsSubmitted { get; set; }
    [Parameter] public int ApplicationId { get; set; }
    [Parameter] public string? ErrorMessage { get; set; }
}

@code {
    private async Task HandleSubmit()
    {
        await OnSubmit.InvokeAsync();
    }
}

arguments.file_text:
@page "/apply"
@namespace sv_16591f20ac524b468d54c549abf405ea.Components.Pages.Apply
@using sv_16591f20ac524b468d54c549abf405ea.Services
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="@currentStep" OnStepSelected="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep @ref="personalInfoStep"
                              FullName="@personalInfo.FullName"
                              Email="@personalInfo.Email"
                              Phone="@personalInfo.Phone"
                              Address="@personalInfo.Address"
                              OnNext="HandlePersonalInfoNext" />
            break;
        case 1:
            <WorkHistoryStep Entries="@workEntries"
                             OnNext="HandleWorkHistoryNext"
                             OnBack="() => GoToStep(0)" />
            break;
        case 2:
            <ReferencesStep References="@references"
                            OnNext="HandleReferencesNext"
                            OnBack="() => GoToStep(1)" />
            break;
        case 3:
            <CoverLetterStep CoverLetterText="@coverLetter"
                             OnNext="HandleCoverLetterNext"
                             OnBack="() => GoToStep(2)" />
            break;
        case 4:
            <ReviewStep Personal="@GetPersonalInfo()"
                        WorkEntries="@workEntries"
                        References="@references"
                        CoverLetter="@coverLetter"
                        OnBack="() => GoToStep(3)"
                        OnEditSection="GoToStep"
                        OnSubmit="HandleSubmit"
                        IsSubmitting="@isSubmitting"
                        IsSubmitted="@isSubmitted"
                        ApplicationId="@applicationId"
                        ErrorMessage="@submitError" />
            break;
    }
</div>

@code {
    private int currentStep = 0;
    private PersonalInfoStep? personalInfoStep;

    // Step 1 data
    private (string FullName, string Email, string Phone, string Address) personalInfo = ("", "", "", "");

    // Step 2 data
    private List<WorkHistoryStep.EntryModel> workEntries = new() { new() };

    // Step 3 data
    private List<ReferencesStep.RefModel> references = new() { new(), new() };

    // Step 4 data
    private string coverLetter = "";

    // Submission state
    private bool isSubmitting;
    private bool isSubmitted;
    private int applicationId;
    private string? submitError;

    private void GoToStep(int step)
    {
        currentStep = step;
        StateHasChanged();
    }

    private async Task HandlePersonalInfoNext(PersonalInfoStep.PersonalInfoResult result)
    {
        var isValidEmail = await ApplicationService.ValidateEmailAsync(result.Email);
        if (!isValidEmail)
        {
            personalInfoStep?.SetEmailError("This email address is not valid.");
            return;
        }

        personalInfo = (result.FullName, result.Email, result.Phone, result.Address);
        currentStep = 1;
    }

    private Task HandleWorkHistoryNext(List<WorkHistoryStep.EntryModel> entries)
    {
        workEntries = entries;
        currentStep = 2;
        return Task.CompletedTask;
    }

    private Task HandleReferencesNext(List<ReferencesStep.RefModel> refs)
    {
        references = refs;
        currentStep = 3;
        return Task.CompletedTask;
    }

    private Task HandleCoverLetterNext(string text)
    {
        coverLetter = text;
        currentStep = 4;
        return Task.CompletedTask;
    }

    private async Task HandleSubmit()
    {
        isSubmitting = true;
        submitError = null;

        try
        {
            var application = new JobApplication(
                GetPersonalInfo(),
                new WorkHistory(workEntries.Select(e => new WorkEntry(
                    e.Company, e.Title, e.StartDate ?? DateTime.MinValue, e.EndDate, e.Description
                )).ToList()),
