@page "/apply"
@namespace sv_16591f20ac524b468d54c549abf405ea.Components.Pages.Apply
@using sv_16591f20ac524b468d54c549abf405ea.Services
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="@currentStep" OnStepSelected="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep @ref="personalInfoStep"
                              FullName="@personalInfo.FullName"
                              Email="@personalInfo.Email"
                              Phone="@personalInfo.Phone"
                              Address="@personalInfo.Address"
                              OnNext="HandlePersonalInfoNext" />
            break;
        case 1:
            <WorkHistoryStep Entries="@workEntries"
                             OnNext="HandleWorkHistoryNext"
                             OnBack="() => GoToStep(0)" />
            break;
        case 2:
            <ReferencesStep References="@references"
                            OnNext="HandleReferencesNext"
                            OnBack="() => GoToStep(1)" />
            break;
        case 3:
            <CoverLetterStep CoverLetterText="@coverLetter"
                             OnNext="HandleCoverLetterNext"
                             OnBack="() => GoToStep(2)" />
            break;
        case 4:
            <ReviewStep Personal="@GetPersonalInfo()"
                        WorkEntries="@workEntries"
                        References="@references"
                        CoverLetter="@coverLetter"
                        OnBack="() => GoToStep(3)"
                        OnEditSection="GoToStep"
                        OnSubmit="HandleSubmit"
                        IsSubmitting="@isSubmitting"
                        IsSubmitted="@isSubmitted"
                        ApplicationId="@applicationId"
                        ErrorMessage="@submitError" />
            break;
    }
</div>

@code {
    private int currentStep = 0;
    private PersonalInfoStep? personalInfoStep;

    // Step 1 data
    private (string FullName, string Email, string Phone, string Address) personalInfo = ("", "", "", "");

    // Step 2 data
    private List<WorkHistoryStep.EntryModel> workEntries = new() { new() };

    // Step 3 data
    private List<ReferencesStep.RefModel> references = new() { new(), new() };

    // Step 4 data
    private string coverLetter = "";

    // Submission state
    private bool isSubmitting;
    private bool isSubmitted;
    private int applicationId;
    private string? submitError;

    private void GoToStep(int step)
    {
        currentStep = step;
        StateHasChanged();
    }

    private async Task HandlePersonalInfoNext(PersonalInfoStep.PersonalInfoResult result)
    {
        var isValidEmail = await ApplicationService.ValidateEmailAsync(result.Email);
        if (!isValidEmail)
        {
            personalInfoStep?.SetEmailError("This email address is not valid.");
            return;
        }

        personalInfo = (result.FullName, result.Email, result.Phone, result.Address);
        currentStep = 1;
    }

    private Task HandleWorkHistoryNext(List<WorkHistoryStep.EntryModel> entries)
    {
        workEntries = entries;
        currentStep = 2;
        return Task.CompletedTask;
    }

    private Task HandleReferencesNext(List<ReferencesStep.RefModel> refs)
    {
        references = refs;
        currentStep = 3;
        return Task.CompletedTask;
    }

    private Task HandleCoverLetterNext(string text)
    {
        coverLetter = text;
        currentStep = 4;
        return Task.CompletedTask;
    }

    private async Task HandleSubmit()
    {
        isSubmitting = true;
        submitError = null;

        try
        {
            var application = new JobApplication(
                GetPersonalInfo(),
                new WorkHistory(workEntries.Select(e => new WorkEntry(
                    e.Company, e.Title, e.StartDate ?? DateTime.MinValue, e.EndDate, e.Description
                )).ToList()),
                references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
                coverLetter
            );

            applicationId = await ApplicationService.SubmitApplicationAsync(application);
            isSubmitted = true;
        }
        catch (Exception ex)
        {
            submitError = $"Submission failed: {ex.Message}";
        }
        finally
        {
            isSubmitting = false;
        }
    }

    private PersonalInfo GetPersonalInfo() =>
        new(personalInfo.FullName, personalInfo.Email, personalInfo.Phone, personalInfo.Address);
}

